    const BUILD={LOURD:{amorti:1.3,stabilite:1.2,protection:1.1,confort:1.1,dynamisme:0.8},TRES_LOURD:{amorti:1.5,stabilite:1.3,protection:1.2,confort:1.1,dynamisme:0.7}};
